$ cat FullG1.java
public class FullG1 {
    public static void main(String[] a) throws Exception {
        List<byte[]> live = new ArrayList<>();      // 계속 쌓인다
        Deque<byte[]> churn = new ArrayDeque<>();
        try {
            for (int i = 0; ; i++) {
                live.add(new byte[32 * 1024]);
                for (int j = 0; j < 8; j++) {
                    churn.add(new byte[16 * 1024]);
                    if (churn.size() > 400) churn.poll();
                }
            }
        } catch (OutOfMemoryError e) { System.out.println("  OOM, live=" + live.size()); }
    }
}

